Here’s a self‑contained Shadertoy-style fragment shader that produces a smooth, hypnotic tunnel/spiral animation.

Paste this into Shadertoy as the `Image` shader (main image) and run:

```glsl
// Hypnotic spiral tunnel
// Paste into Shadertoy's Image tab

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1 with aspect correction)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float t = iTime;

    // Convert to polar
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // Spiral / tunnel controls
    float spiralSpeed  = 0.35;
    float radialFreq   = 18.0;
    float angularFreq  = 8.0;
    float tunnelScroll = t * 1.4;

    // Base spiral pattern:
    // Use radius and angle, plus time, to create waves that move inward
    float wave = r * radialFreq
                 - a * angularFreq
                 - tunnelScroll;

    // Repeat waves
    float stripe = 0.5 + 0.5 * sin(wave);

    // Add a secondary phase‑shifted wave for interference
    float wave2   = r * (radialFreq * 0.6)
                  + a * (angularFreq * 1.3)
                  + t * spiralSpeed * 2.0;
    float stripe2 = 0.5 + 0.5 * sin(wave2);

    // Combine and sharpen “rings”
    float rings = pow(stripe * stripe2, 2.0);

    // Radial falloff to keep center bright and edges calm
    float vignette = smoothstep(1.2, 0.1, r);

    // Subtle rotation over time for added hypnosis
    float rot = 0.15 * t;
    float ca = cos(rot);
    float sa = sin(rot);
    vec2 uvRot = mat2(ca, -sa, sa, ca) * uv;

    // Use rotated angle for color variation
    float a2 = atan(uvRot.y, uvRot.x);

    // Color palette based on angle and time
    vec3 baseCol = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + a2 * 2.5 + t * 0.8);

    // Modulate brightness with rings and vignette
    float brightness = rings * vignette;

    // Add a subtle pulsation
    float pulse = 0.7 + 0.3 * sin(t * 1.5);
    brightness *= pulse;

    vec3 col = baseCol * brightness;

    // Slight gamma correction
    col = pow(col, vec3(0.9));

    fragColor = vec4(col, 1.0);
}
```

If you’d like, I can tweak it toward a specific style (e.g., black‑and‑white spiral, more colorful nebula, slower/faster movement).

